code='''from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            colors={grid[y][x] for y,x in cells}
            boxes={}
            for col in colors:
                pts=[(y,x) for y,x in cells if grid[y][x]==col]
                boxes[col]=(max(y for y,x in pts)-min(y for y,x in pts)+1)*(max(x for y,x in pts)-min(x for y,x in pts)+1)
            order=sorted(colors,key=lambda z:boxes[z],reverse=True)
            mapping={a:b for a,b in zip(order,reversed(order))}
            for y,x in cells: out[y][x]=mapping[grid[y][x]]
    return out
'''
